import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"UGSo Spezial","description":"Animated SVG lines and summing nodes for ioBroker VIS 2.","frontmatter":{"title":"UGSo Spezial","description":"Animated SVG lines and summing nodes for ioBroker VIS 2."},"headers":[],"relativePath":"en/iobroker/widgets/ugso-spezial/index.md","filePath":"en/iobroker/widgets/ugso-spezial/index.md","lastUpdated":1793807739000}'),r={name:"en/iobroker/widgets/ugso-spezial/index.md"};function n(s,e,l,d,p,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ugso-spezial" tabindex="-1">UGSo Spezial <a class="header-anchor" href="#ugso-spezial" aria-label="Permalink to &quot;UGSo Spezial&quot;">​</a></h1><p><strong>UGSo Spezial</strong> visualizes data flows in VIS 2, such as power readings from several devices. The set contains two widgets.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><ul><li><strong>SVG-Line</strong> connects points with straight, right-angle or waypoint routes. Colors, dash lengths and arrowheads are configurable. Positive values animate forward, negative values reverse the direction, and zero stops the animation. Speed can be fixed or proportional to the absolute value.</li><li><strong>SVG LineBox</strong> adds up to four input lines and an optional correction value. It can send the total to up to two output lines or write it in the runtime view to an existing writable numeric state under <code>0_userdata.0</code>. If a selected input is unavailable, the node waits for its value.</li></ul><p>In the editor, drag a yellow endpoint to snap it to another line or LineBox. An endpoint with an arrowhead cannot snap. Snapping aligns the graphics; configure value routing separately in the LineBox.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>A running VIS 2 installation is required. Install the widget set from its GitHub URL in ioBroker Admin (expert mode). Restart VIS 2 after updates to load the new version. Both widgets appear under <strong>UGSo Spezial</strong> in the editor palette.</p><ul><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-spezial" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-spezial/releases" target="_blank" rel="noreferrer">Releases</a></li><li><a href="https://www.npmjs.com/package/iobroker.vis-2-widgets-ugso-spezial" target="_blank" rel="noreferrer">npm</a></li></ul>',8)])])}const c=t(r,[["render",n]]);export{h as __pageData,c as default};
